using CheckInApp.Application;
using CheckInApp.Domain;
using CheckInApp.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace CheckInApp.Api;
[ApiController,Authorize,Route("api/v1/users")]
public class AccountManagementController(AppDbContext db,AccessService access):ControllerBase
{
 public record EditInput(string FullName,string Email,string Reason,string ExpectedFullName,string ExpectedEmail,Guid? RoleId=null,Guid? CatechistId=null,Guid? ProfileVersion=null);
 Guid Actor=>Guid.Parse(User.FindFirst("sub")!.Value);
 async Task<AppUser> Target(Guid id,CancellationToken ct){await access.Require(Actor,Permission.UserManage,ct);var caller=await access.Rights(Actor,ct);var roles=await(from u in db.UserRoles join r in db.Roles on u.RoleId equals r.Id where u.UserId==id select r).ToListAsync(ct);if(roles.Any(r=>(r.Permissions&caller.Mask)!=r.Permissions||r.GlobalScope&&!caller.Global))throw new AppException(403,"GRANT_SCOPE","Không quản lý tài khoản có quyền cao hơn.");return await db.Users.SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new AppException(404,"NOT_FOUND","Không có tài khoản.");}
 [HttpPut("{id:guid}/profile")] public async Task<IActionResult> Edit(Guid id,EditInput input,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var user=await Target(id,ct);var profileVersion=await db.Audit.Where(a=>a.EntityId==id&&a.Action=="EditProfile").OrderByDescending(a=>a.CreatedAtUtc).ThenByDescending(a=>a.Id).Select(a=>(Guid?)a.Id).FirstOrDefaultAsync(ct);if(profileVersion!=input.ProfileVersion)throw new AppException(409,"VERSION_CONFLICT","Thông tin đã thay đổi, tải lại trước khi sửa.");if(user.FullName!=input.ExpectedFullName||user.Email!=input.ExpectedEmail)throw new AppException(409,"VERSION_CONFLICT","Thông tin đã thay đổi, tải lại trước khi sửa.");var name=input.FullName?.Trim();var email=input.Email?.Trim().ToLowerInvariant();if(string.IsNullOrWhiteSpace(name)||name.Length>200||!System.Net.Mail.MailAddress.TryCreate(email,out _)||string.IsNullOrWhiteSpace(input.Reason)||input.Reason.Length>500)throw new AppException(400,"VALIDATION","Kiểm tra họ tên, email và lý do.");if(await db.Users.AnyAsync(x=>x.Id!=id&&x.Email==email,ct))throw new AppException(409,"EMAIL_EXISTS","Email đã được sử dụng.");if(input.RoleId!=null){await access.Require(Actor,Permission.RoleManage,ct);var role=await db.Roles.SingleOrDefaultAsync(x=>x.Id==input.RoleId,ct)??throw new AppException(400,"ROLE_INVALID","Vai trò không hợp lệ.");var rights=await access.Rights(Actor,ct);if((role.Permissions&rights.Mask)!=role.Permissions||role.GlobalScope&&!rights.Global)throw new AppException(403,"GRANT_SCOPE","Không cấp quyền vượt quyền hiện tại.");var adminIds=await(from ur in db.UserRoles join r in db.Roles on ur.RoleId equals r.Id where r.Name=="Admin" select ur.UserId).ToListAsync(ct);if(adminIds.Contains(id)&&role.Name!="Admin"&&await db.Users.CountAsync(x=>adminIds.Contains(x.Id)&&x.Status==AccountStatus.Active,ct)<=1)throw new AppException(409,"LAST_ADMIN","Không hạ quyền admin cuối cùng.");if(!role.GlobalScope&&input.CatechistId==null)throw new AppException(400,"CATECHIST_REQUIRED","Vai trò theo lớp cần GLV liên kết.");if(input.CatechistId!=null){var teacher=await db.Catechists.SingleOrDefaultAsync(x=>x.Id==input.CatechistId,ct)??throw new AppException(400,"CATECHIST_INVALID","GLV không hợp lệ.");if(teacher.UserId!=null&&teacher.UserId!=id)throw new AppException(409,"CATECHIST_LINKED","GLV đã liên kết tài khoản khác.");foreach(var old in await db.Catechists.Where(x=>x.UserId==id&&x.Id!=input.CatechistId).ToListAsync(ct))old.UserId=null;teacher.UserId=id;}db.UserRoles.RemoveRange(await db.UserRoles.Where(x=>x.UserId==id).ToListAsync(ct));db.UserRoles.Add(new(){UserId=id,RoleId=role.Id});}var before=new{user.FullName,user.Email};user.FullName=name;user.Email=email!;foreach(var session in await db.AuthSessions.Where(x=>x.UserId==id&&!x.Revoked).ToListAsync(ct)){session.Revoked=true;session.Version=Guid.NewGuid();}db.Audit.Add(new(){ActorId=Actor,EntityId=id,EntityType="User",Action="EditProfile",Detail=System.Text.Json.JsonSerializer.Serialize(new{before,after=new{user.FullName,user.Email},input.Reason,input.RoleId,input.CatechistId})});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return NoContent();}
 [HttpPost("{id:guid}/reconsider")] public async Task<IActionResult> Reconsider(Guid id,[FromBody] Dictionary<string,string> input,CancellationToken ct){await access.Require(Actor,Permission.UserApprove,ct);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var user=await Target(id,ct);if(user.Status is not(AccountStatus.Suspended or AccountStatus.Rejected))throw new AppException(409,"ACCOUNT_STATE","Chỉ xem xét lại tài khoản khóa hoặc từ chối.");if(!input.TryGetValue("reason",out var reason)||string.IsNullOrWhiteSpace(reason)||reason.Length>500)throw new AppException(400,"REASON_REQUIRED","Cần lý do xem xét lại.");user.Status=AccountStatus.PendingApproval;db.Audit.Add(new(){ActorId=Actor,EntityId=id,EntityType="User",Action="Reconsider",Detail=reason});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return NoContent();}
}
